 (\textbf{Distance-from-$\mathbf{Z}$})
Let $\mathbf{X,Y}$ and $\mathbf{Z}$ be pairwise disjoint node sets in a maximal $\mathrm{PDAG}${} $\g$. Let $p$ be a path from $\mathbf{X}$ to $\mathbf{Y}$ in~$\g$ such that every collider $C$ on $p$ has a b-possibly causal path to $\mathbf{Z}$. Define the $distance-from-\!{\mathbf{Z}}$ of collider $C$ to be the length of a shortest b-possibly causal path from $C$ to $\mathbf{Z}$, and define the $distance-from-\!{\mathbf{Z}}$ of $p$ to be the sum of the distances from $\mathbf{Z}$ of the colliders on $p$.
\label{def:distance from Z}

 \citep[Lemma~A.7 in][]{ernestroth2016}
Let $X$ and $Y$ be nodes in a  maximal $\mathrm{PDAG}${} $\g$ such that $X - Y$ is in $\g$. Let $\g' = \mathrm{ConstructMaxPDAG}(\g,\{X \rightarrow Y\})$. For any $Z,W \in \mathbf{V}$ if $Z \rightarrow W$ is in $\g'$ and $Z -W$ is in $\g$, then $W \in \mathrm{De}(Y,\g')$.
\label{lemma:alwaydesc}

 \citep[cf.\ Lemma~A.8 in][]{ernestroth2016}
Let $X$ be a node in a maximal $\mathrm{PDAG}${} $\g$. Then there is a maximal $\mathrm{PDAG}${} $\g'$ in $[\g]$ such that $X \rightarrow S$ is in $\g'$ for all $S \in \mathrm{Sib}(X,\g)$. 
\label{lemma:no-new-into}

  Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a maximal $\mathrm{PDAG}${} $\g$. If $\g$ is b-amenable relative to $(\mathbf{X},\mathbf{Y})$, then the following statements are equivalent:
\begin{enumerate}[label = (\roman*)]
\item\label{l:eqa1-pdag} $\mathbf{Z}$ satisfies the b-forbidden set condition{} (see Definition~\ref{def:gac-pdag}) relative to $(\mathbf{X},\mathbf{Y})$ in~$\g$.
\item\label{l:eqa2-pdag}  $\mathbf{Z}$ satisfies the b-forbidden set condition{} relative to $(\mathbf{X},\mathbf{Y})$ in every $\mathrm{DAG}$ in $[\g]$.
\end{enumerate}
   \label{lemma:eqpdag}

Let $\mathbf{X,Y}$ and $\mathbf{Z}$ be pairwise disjoint node sets in a maximal $\mathrm{PDAG}${} $\g$. Let $\mathbf{Z}$ satisfy the b-amenability condition{} and the b-forbidden set condition{} relative to $(\mathbf{X},\mathbf{Y})$ in~$\g$. Let $\g[D]$ be a $\mathrm{DAG}$ in $[\g]$ and let $p = \langle X = V_{0}, V_{1},\dots ,V_{k} = Y \rangle, k \ge 1,$ be a proper non-causal path from $X \in \mathbf{X}$ to $Y \in \mathbf{Y}$ that is d-connecting given $\mathbf{Z}$ in~$\g[D]$. Let $\pstar$ in~$\g$ denote the path corresponding to $p$. Then:
\begin{enumerate}[label=(\roman*)]
\item\label{l:ncp:pdag} Let $i,j \in \mathbb{N}, 0 < i < j \leq k,$ such that there is an edge $\langle V_i, V_j \rangle$ in~$\g$. The path $ \pstar(X,V_i) \oplus \langle V_i, V_j \rangle \oplus \pstar(V_j,Y)$ ($\pstar(V_j, Y)$ is possibly of zero length) is a proper b-non-causal path in~$\g$. For $j=i+1$, this implies that $\pstar$ is a proper b-non-causal path.
\item\label{l:ncp:b-pdag-new} If $X \leftarrow V_1$ and $V_1 \rightarrow V_2$ are not in $\g$ and there is an edge $\langle X,V_2 \rangle$ in $\g$, then $\pstar[q]=\langle X,V_2 \rangle \oplus \pstar(V_2,Y)$, ($\pstar(V_2, Y)$ is possibly of zero length) is a proper b-non-causal path in~$\g$.
\end{enumerate}
\label{lemma:non-causal-path-pdag}
